<section data-step="3" class="hidden"><h2 class="text-2xl font-bold">أسئلة سلامة قصيرة</h2><div class="mt-6 space-y-4">@foreach(['published'=>'هل نُشر المحتوى بالفعل؟','account'=>'هل لدى الشخص وصول إلى حسابك؟','danger'=>'هل يوجد خطر جسدي مباشر؟','minor'=>'هل المتأثر دون 18 عاماً؟'] as $field=>$label)<label class="flex cursor-pointer justify-between rounded-2xl border p-4"><span>{{ $label }}</span><input data-safety="{{ $field }}" type="checkbox" class="size-5"></label>@endforeach</div></section>
