<div class="mt-8 flex justify-between"><button type="button" id="previous" class="invisible rounded-xl border px-5 py-3 font-bold">السابق</button><button type="button" id="next" class="rounded-xl bg-brand px-6 py-3 font-bold text-white">التالي</button></div>
</div></div></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{let step=1,threat='';const root=document.querySelector('#help-wizard'),next=root.querySelector('#next'),previous=root.querySelector('#previous');const show=()=>{root.querySelectorAll('[data-step]').forEach(x=>x.classList.toggle('hidden',Number(x.dataset.step)!==step));root.querySelectorAll('#progress span').forEach((x,i)=>{x.classList.toggle('bg-brand',i<step);x.classList.toggle('bg-slate-200',i>=step)});root.querySelector('#step-label').textContent=`الخطوة ${step} من 4`;previous.classList.toggle('invisible',step===1);next.textContent=step===4?'العودة للرئيسية':'التالي'};root.querySelectorAll('[data-threat]').forEach(button=>button.addEventListener('click',()=>{threat=threat===button.dataset.threat?'':button.dataset.threat;root.querySelectorAll('[data-threat]').forEach(x=>{const selected=x.dataset.threat===threat;x.classList.toggle('border-brand',selected);x.classList.toggle('bg-blue-50',selected);x.querySelector('.check').textContent=selected?'✓':''});root.querySelector('[data-error="threat"]').classList.add('hidden')}));next.addEventListener('click',()=>{if(step===1&&!threat){root.querySelector('[data-error="threat"]').classList.remove('hidden');return}if(step===2&&!root.querySelector('#country').value){root.querySelector('[data-error="country"]').classList.remove('hidden');return}if(step===4){location.href='{{ route('home') }}';return}step++;if(step===4){root.querySelector('#danger-guidance').classList.toggle('hidden',!root.querySelector('[data-safety="danger"]').checked);root.querySelector('#child-guidance').classList.toggle('hidden',!(root.querySelector('[data-safety="minor"]').checked||threat==='child'))}show()});previous.addEventListener('click',()=>{if(step>1){step--;show()}});root.querySelector('#country').addEventListener('change',e=>{if(e.target.value)root.querySelector('[data-error="country"]').classList.add('hidden')});show()});
</script>
@endsection
